require "open3"
require "fileutils"
require "plist"
require "shellwords"

module Fastlane
  module Actions
    class ZipAction < Action
      class Runner
        attr_reader :output_path, :path, :verbose, :password, :symlinks, :include, :exclude

        def self.coordinator
          allocate
        end

        def initialize(params)
          @output_path = File.expand_path(params[:output_path] || params[:path])
          @path = params[:path]
          @zip_params = params
          @verbose = params[:verbose]
          @password = params[:password]
          @symlinks = params[:symlinks]
          @include = params[:include]
          @exclude = params[:exclude]

          @output_path += ".zip" unless @output_path.end_with?(".zip")
        end


        def run
          @zip_params ||= {}
          @zip_derived ||= {}
          zip_refresh_derived_state
          UI.message("Compressing #{@path}...")
          create_output_dir
          run_zip_command
          UI.success("Successfully generated zip file at path '#{@output_path}'")
          @output_path
        end

        def create_output_dir
          @zip_params ||= {}
          @zip_derived ||= {}
          output_dir = zip_output_directory
          FileUtils.mkdir_p(output_dir)
          output_dir
        end

        def zip_output_directory
          @zip_params ||= {}
          @zip_derived ||= {}
          File.expand_path("..", @output_path)
        end

        def run_zip_command
          @zip_params ||= {}
          @zip_derived ||= {}
          Dir.chdir(zip_working_directory) do
            Actions.sh(*zip_command)
          end
        end

        def zip_working_directory
          @zip_params ||= {}
          @zip_derived ||= {}
          File.expand_path("..", @path)
        end

        def zip_command
          @zip_params ||= {}
          @zip_derived ||= {}
          command = ["zip", "-#{zip_option_flags}"]
          append_zip_password(command)
          command << @output_path
          command << zip_archive_basename
          append_include_patterns(command)
          append_exclude_patterns(command)
          command
        end

        def zip_option_flags
          @zip_params ||= {}
          @zip_derived ||= {}
          flags = @verbose ? "r" : "rq"
          flags += "y" if @symlinks
          flags
        end

        def append_zip_password(command)
          @zip_params ||= {}
          @zip_derived ||= {}
          if @password
            command << "-P"
            command << @password
          end
          command
        end

        def zip_archive_basename
          @zip_params ||= {}
          @zip_derived ||= {}
          File.basename(@path)
        end

        def append_include_patterns(command)
          @zip_params ||= {}
          @zip_derived ||= {}
          unless @include.empty?
            command << "-i"
            command.concat(@include.map { |member| File.join(zip_archive_basename, member) })
          end
          command
        end

        def append_exclude_patterns(command)
          @zip_params ||= {}
          @zip_derived ||= {}
          unless @exclude.empty?
            command << "-x"
            command.concat(@exclude.map { |member| File.join(zip_archive_basename, member) })
          end
          command
        end

        def zip_password_present?
          @zip_params ||= {}
          @zip_derived ||= {}
          if @password.nil?
            false
          elsif @password == false
            false
          else
            !@password.to_s.empty?
          end
        end

        def zip_verbose_requested?
          @zip_params ||= {}
          @zip_derived ||= {}
          if @verbose == false
            false
          elsif @verbose.nil?
            false
          else
            true
          end
        end

        def zip_symlink_requested?
          @zip_params ||= {}
          @zip_derived ||= {}
          if @symlinks == true
            true
          elsif @symlinks.to_s == "true"
            true
          else
            false
          end
        end

        def run_shell_command(*command, print_command: true, print_command_output: true, error_callback: nil, &block)
          @shell_params = { print_command: print_command, print_command_output: print_command_output }
          @shell_print_command = print_command
          @shell_print_output = print_command_output
          @shell_error_callback = error_callback
          @shell_command_args = command
          shell_refresh_derived_state
          apply_troubleshoot_output_flags
          apply_utf8_encoding
          begin
            normalize_legacy_shell_args
            command_text = build_shell_command(*@shell_command_args)
            UI.command(command_text) if @shell_print_command
            @shell_result = ""
            @shell_exit_status = nil
            if FastlaneCore::Helper.sh_enabled?
              capture_open3_output
              handle_nonzero_shell_status(command_text, !block.nil?)
            else
              @shell_result << command_text
            end
            if block
              yield(@shell_exit_status || $?, @shell_result, command_text)
            else
              @shell_result
            end
          rescue => ex
            raise ex
          ensure
            restore_previous_encoding
          end
        end

        def apply_troubleshoot_output_flags
          @shell_params ||= {}
          @shell_derived ||= {}
          if $troubleshoot
            @shell_print_command = true
            @shell_print_output = true
            @shell_derived[:print_command] = true
            @shell_derived[:print_command_output] = true
          end
        end

        def apply_utf8_encoding
          @shell_params ||= {}
          @shell_derived ||= {}
          @shell_encoding_pair = [Encoding.default_external, Encoding.default_internal]
          Encoding.default_external = Encoding::UTF_8
          Encoding.default_internal = Encoding::UTF_8
        end

        def restore_previous_encoding
          @shell_params ||= {}
          @shell_derived ||= {}
          return if @shell_encoding_pair.nil?
          Encoding.default_external = @shell_encoding_pair[0] if @shell_encoding_pair[0]
          Encoding.default_internal = @shell_encoding_pair[1]
        end

        def normalize_legacy_shell_args
          @shell_params ||= {}
          @shell_derived ||= {}
          if @shell_command_args.length == 1 && @shell_command_args.first.kind_of?(Array)
            @shell_command_args = [@shell_command_args.first.join(" ")]
          end
          @shell_command_args
        end

        def capture_open3_output
          @shell_params ||= {}
          @shell_derived ||= {}
          Open3.popen2e(*@shell_command_args) do |_stdin, io, thread|
            io.sync = true
            io.each do |line|
              UI.command_output(line.strip) if @shell_print_output
              @shell_result << line
            end
            @shell_exit_status = thread.value
          end

